import zipfile
import csv
import json

def parse_gtfs(zip_path, output_path):
    mandatory_files = {
        'stops.txt': 'has_stops',
        'routes.txt': 'has_routes',
        'trips.txt': 'has_trips',
        'stop_times.txt': 'has_stop_times'
    }
    row_counts = {
        'n_stops': 0,
        'n_routes': 0,
        'n_trips': 0,
        'n_stop_times': 0
    }
    summary = {}

    with zipfile.ZipFile(zip_path, 'r') as z:
        for file_name, summary_key in mandatory_files.items():
            if file_name in z.namelist():
                summary[summary_key] = True
                with z.open(file_name) as f:
                    reader = csv.DictReader(line.decode('utf-8') for line in f)
                    row_counts[f'n_{file_name.split(".")[0]}'] = sum(1 for _ in reader)
            else:
                summary[summary_key] = False

    for key in row_counts.keys():
        summary[key] = row_counts[key]

    with open(output_path, 'w') as outfile:
        json.dump(summary, outfile, indent=4)

parse_gtfs('inputs/gtfs/sample_city_gtfs.zip', 'outputs/t04_gtfs_summary.json')

